<?php
require_once '../includes/config.php';require_once '../includes/database.php';$db=new Database();$pdo=$db->getConnection();$q=trim($_GET['q']??'');$where='';$params=[];if($q!==''){$where='WHERE f.flight_number LIKE ? OR oa.airport_name LIKE ? OR da.airport_name LIKE ?';$p='%'.$q.'%';$params=[$p,$p,$p];}$stmt=$pdo->prepare("SELECT f.flight_number,f.departure_time,f.arrival_time,f.status,a.airline_name,oa.airport_name origin,da.airport_name destination FROM flights f JOIN airlines a ON f.airline_id=a.id JOIN airports oa ON f.origin_airport_id=oa.id JOIN airports da ON f.destination_airport_id=da.id $where ORDER BY f.departure_time DESC LIMIT 100");$stmt->execute($params);$rows=$stmt->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Flight Status</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><div class="container py-5"><h2>Flight Status</h2><form class="mb-3"><input class="form-control" name="q" value="<?=htmlspecialchars($q)?>" placeholder="Search flight or airport"></form><table class="table table-hover"><thead><tr><th>Flight</th><th>Airline</th><th>Route</th><th>Departure</th><th>Arrival</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=htmlspecialchars($r['flight_number'])?></td><td><?=htmlspecialchars($r['airline_name'])?></td><td><?=htmlspecialchars($r['origin'])?> → <?=htmlspecialchars($r['destination'])?></td><td><?=htmlspecialchars($r['departure_time'])?></td><td><?=htmlspecialchars($r['arrival_time'])?></td><td><span class="badge text-bg-primary"><?=htmlspecialchars($r['status'])?></span></td></tr><?php endforeach;?></tbody></table></div></body></html>